DROP TABLE IF EXISTS `bookings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `booking_no` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int unsigned NOT NULL,
  `costume_id` int unsigned NOT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `channel` enum('online','counter') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'online',
  `event_date` date NOT NULL,
  `pickup_date` date NOT NULL,
  `pickup_time` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '13:00',
  `return_date` date NOT NULL,
  `return_time` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '13:00',
  `delivery_method` enum('pickup','post','messenger') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pickup' COMMENT 'รับที่ร้าน / ส่งพัสดุ / เมสเซนเจอร์',
  `return_method` enum('store','post') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'store' COMMENT 'คืนที่ร้าน / ส่งพัสดุคืน',
  `ship_zone` enum('metro','upcountry') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ship_by_date` date DEFAULT NULL COMMENT 'วันที่ร้านต้องส่งพัสดุให้ถึงลูกค้าทันวันรับชุด',
  `ship_recipient` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ship_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ship_address` varchar(600) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ที่อยู่จัดส่ง ณ ตอนจอง (แก้สมุดที่อยู่ภายหลังไม่กระทบ)',
  `ship_province` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ship_postcode` char(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `block_from` date NOT NULL COMMENT 'วันแรกที่ชุดไม่ว่าง (วันส่งพัสดุ หรือวันรับชุดที่ร้าน)',
  `block_until` date NOT NULL COMMENT 'วันสุดท้ายที่ชุดไม่ว่าง (รวมวันขนส่งกลับและวันซัก)',
  `rental_days` smallint unsigned NOT NULL,
  `rent_amount` decimal(10,2) NOT NULL,
  `extra_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `deposit_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `delivery_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าส่งชุดถึงลูกค้า',
  `return_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าใบปะหน้าส่งคืน (ร้านแนบไว้ในกล่อง)',
  `total_amount` decimal(10,2) NOT NULL COMMENT 'ยอดที่ต้องชำระตอนจอง = ค่าเช่า + ค่าวันเพิ่ม + มัดจำ + ค่าส่ง',
  `status` enum('pending_payment','awaiting_verification','confirmed','shipped','picked_up','returning','returned','cancelled','expired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_payment',
  `hold_expires_at` datetime DEFAULT NULL,
  `note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `staff_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancel_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancelled_by` int unsigned DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `refund_amount` decimal(10,2) DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `picked_up_at` datetime DEFAULT NULL,
  `returned_at` datetime DEFAULT NULL,
  `late_days` smallint unsigned NOT NULL DEFAULT '0',
  `late_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `damage_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `damage_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deposit_refund` decimal(10,2) DEFAULT NULL,
  `extra_charge` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าปรับส่วนที่เกินเงินมัดจำ',
  `inspected_at` datetime DEFAULT NULL,
  `inspected_by` int unsigned DEFAULT NULL,
  `inspection_json` text COLLATE utf8mb4_unicode_ci COMMENT 'ผลตรวจสภาพตอนรับคืน: จุดที่ตรวจ ของที่ขาด สภาพชุดหลังตรวจ',
  `arrival_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ลูกค้าแจ้งปัญหาตอนได้รับพัสดุ',
  `arrival_reported_at` datetime DEFAULT NULL,
  `dispute_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ลูกค้าโต้แย้งค่าเสียหาย',
  `dispute_at` datetime DEFAULT NULL,
  `dispute_reply` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dispute_resolved_at` datetime DEFAULT NULL,
  `damage_waived` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'ค่าเสียหายที่ร้านลดให้หลังทบทวน (คืนเงินแล้ว)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_booking_no` (`booking_no`),
  KEY `idx_booking_costume_dates` (`costume_id`,`status`,`block_from`,`block_until`),
  KEY `idx_booking_user` (`user_id`,`status`),
  KEY `idx_booking_pickup` (`pickup_date`),
  KEY `idx_booking_ship` (`status`,`ship_by_date`),
  KEY `idx_booking_return` (`return_date`),
  KEY `fk_booking_creator` (`created_by`),
  CONSTRAINT `fk_booking_costume` FOREIGN KEY (`costume_id`) REFERENCES `costumes` (`id`),
  CONSTRAINT `fk_booking_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_booking_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

