INSERT INTO `mail_outbox` VALUES (1,'member@panteen.test','ส่งชุดแล้ว PT69-0045 · เลขพัสดุ EF100000016TH','<!doctype html>\n<html lang=\"th\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width\"><title>ส่งชุดแล้ว PT69-0045 · เลขพัสดุ EF100000016TH</title></head>\n<body style=\"margin:0;background:#F4F2EF;font-family:\'Anuphan\',\'Sukhumvit Set\',\'Thonburi\',\'Leelawadee UI\',Tahoma,sans-serif;color:#131110\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#F4F2EF\"><tr><td align=\"center\" style=\"padding:32px 12px\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border:1px solid #DEDAD4\">\n<tr><td style=\"padding:30px 32px 24px;border-bottom:1px solid #131110;font:400 19px/1.2 Didot,\'Bodoni MT\',\'Bodoni 72\',\'Times New Roman\',Georgia,serif;letter-spacing:5px;text-transform:uppercase;color:#131110\">Panteen Rent</td></tr>\n<tr><td style=\"padding:28px 32px 32px;font-size:15px;line-height:1.75;color:#131110\"><p style=\"margin:0 0 12px;color:#4A4643\">สวัสดีคุณพิม</p><h1 style=\"margin:0 0 14px;font-size:24px;line-height:1.35;font-weight:300;color:#131110\">ชุดของคุณออกจากร้านแล้ว</h1>\n<p style=\"margin:0 0 8px\">ไปรษณีย์ไทย (EMS / ลงทะเบียน) เลขพัสดุ EF100000016TH ติดตามได้ที่ https://track.thailandpost.co.th/</p><p style=\"margin:0 0 8px\">เมื่อได้รับ เปิดกล่องตรวจชุดและของที่มากับชุด แล้วกด “ได้รับชุดแล้ว” พร้อมถ่ายรูปสภาพชุดในหน้าการจอง</p><p style=\"margin:0 0 8px\">ถ้าพบปัญหา แจ้งร้านภายใน 24 ชั่วโมงหลังได้รับ เพื่อไม่ให้ถูกคิดค่าเสียหายที่ไม่ได้เกิดจากคุณ</p><p style=\"margin:0 0 8px\">เก็บกล่องและใบปะหน้าส่งคืนไว้ ใช้ส่งชุดกลับภายใน 25 พ.ย. 2569</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:20px 0 4px;border-top:1px solid #131110;font-size:14px\">\n<tr><td style=\"padding:10px 16px 10px 0;color:#6E6964;border-bottom:1px solid #ECE9E4;white-s