DROP TABLE IF EXISTS `shipments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shipments` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `booking_id` int unsigned NOT NULL,
  `direction` enum('out','back') COLLATE utf8mb4_unicode_ci NOT NULL,
  `carrier` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tracking_no` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipped_on` date NOT NULL COMMENT 'วันที่ฝากส่ง (ขากลับใช้คิดว่าคืนช้าหรือไม่)',
  `status` enum('in_transit','delivered','failed','received','lost') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_transit',
  `arrived_at` datetime DEFAULT NULL COMMENT 'ถึงลูกค้า (ขาไป) หรือถึงร้าน (ขากลับ)',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_shipment_booking` (`booking_id`,`direction`),
  KEY `idx_shipment_status` (`status`,`direction`),
  CONSTRAINT `fk_shipment_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
